const rows = $input.all().map(i => i.json);
const proj = rows[0] || {};
const total = rows.reduce((s, r) => s + Number(r.allocated_amount ?? 0), 0);
const lines = rows.filter(r => r.division_code).map(r => `<tr><td>${r.division_code ?? ''}</td><td>${r.scope_description ?? ''}</td><td>$${Number(r.allocated_amount ?? 0).toLocaleString('en-US')}</td></tr>`).join('');
const form = `<form method='POST' action='/webhook/estimate/approval'><input type='hidden' name='token' value='${proj.token ?? ''}'><input type='hidden' name='approval_method' value='onsite_link'><input type='text' name='signer_name' placeholder='Type your full name' required><br><button class='btn approve' name='decision' value='approve'>Approve</button><button class='btn reject' name='decision' value='reject'>Reject</button></form>`;
const html = `<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>Approve Estimate</title><style>body{font-family:Helvetica,Arial,sans-serif;color:#1e293b;margin:2rem;max-width:640px}h1{font-size:1.4rem;color:#2563eb}table{width:100%;border-collapse:collapse}td,th{padding:.5rem;border-bottom:1px solid #e2e8f0;text-align:left}.total{font-size:1.3rem;font-weight:700;margin-top:1rem}input[type=text]{width:100%;padding:.6rem;margin:1rem 0;font-size:1rem;box-sizing:border-box}.btn{padding:.7rem 1.2rem;border:none;border-radius:6px;font-size:1rem;cursor:pointer;margin-right:.5rem}.approve{background:#16a34a;color:#fff}.reject{background:#dc2626;color:#fff}</style></head><body><h1>Baseline Estimate — ${proj.title ?? ''}</h1>${proj.baseline_status === 'PENDING' ? `<table><tr><th>Division</th><th>Scope</th><th>Amount</th></tr>${lines}</table><div class='total'>Total: $${total.toLocaleString('en-US')}</div>${form}` : `<p>This baseline estimate is already ${(proj.baseline_status ?? '').toLowerCase()}.</p>`}</body></html>`;
return [{ json: { html } }];

const r = $input.first()?.json;
const ok = r && r.baseline_status === 'APPROVED';
const html = `<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>${ok ? 'Approved' : 'Decision recorded'}</title><style>body{font-family:Helvetica,Arial,sans-serif;color:#1e293b;margin:2rem;text-align:center}.ok{color:#16a34a;font-size:1.5rem;font-weight:700}.no{color:#dc2626;font-size:1.5rem;font-weight:700}</style></head><body><div class='${ok ? 'ok' : 'no'}'>${ok ? 'Approved' : 'Decision recorded'}</div><p>${r?.title ?? ''}</p>${ok ? `<p>Revised contract: $${Number(r.revised_contract_value ?? 0).toLocaleString('en-US')}</p>` : ''}</body></html>`;
return [{ json: { html } }];

const co = $input.first()?.json;
const amount = Number(co?.cost_impact ?? 0);
const sign = amount >= 0 ? '+' : '';
const form = `<form method='POST' action='/webhook/change-order/approval'><input type='hidden' name='token' value='${co?.token ?? ''}'><input type='hidden' name='approval_method' value='onsite_link'><input type='text' name='signer_name' placeholder='Type your full name' required><br><button class='btn approve' name='decision' value='approve'>Approve</button><button class='btn reject' name='decision' value='reject'>Reject</button></form>`;
const html = `<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>Approve Change Order</title><style>body{font-family:Helvetica,Arial,sans-serif;color:#1e293b;margin:2rem;max-width:640px}h1{font-size:1.4rem;color:#2563eb}.amount{font-size:1.6rem;font-weight:700}.row{display:flex;justify-content:space-between;padding:.4rem 0;border-bottom:1px solid #e2e8f0}input[type=text]{width:100%;padding:.6rem;margin:1rem 0;font-size:1rem;box-sizing:border-box}.btn{padding:.7rem 1.2rem;border:none;border-radius:6px;font-size:1rem;cursor:pointer;margin-right:.5rem}.approve{background:#16a34a;color:#fff}.reject{background:#dc2626;color:#fff}</style></head><body><h1>Change Order #${co?.change_order_number ?? ''} — ${co?.project_name ?? ''}</h1><div class='row'><span>Description</span><span>${co?.description ?? ''}</span></div><div class='row'><span>Impact</span><span class='amount'>${sign}$${Math.abs(amount).toLocaleString('en-US')}</span></div>${co?.approval_status === 'PENDING' ? form : `<p>This change order is already ${(co?.approval_status ?? '').toLowerCase()}.</p>`}</body></html>`;
return [{ json: { html } }];

const r = $input.first()?.json;
const ok = r && r.approval_status === 'APPROVED';
const html = `<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>${ok ? 'Approved' : 'Decision recorded'}</title><style>body{font-family:Helvetica,Arial,sans-serif;color:#1e293b;margin:2rem;text-align:center}.ok{color:#16a34a;font-size:1.5rem;font-weight:700}.no{color:#dc2626;font-size:1.5rem;font-weight:700}</style></head><body><div class='${ok ? 'ok' : 'no'}'>${ok ? 'Approved' : 'Decision recorded'}</div><p>Change order #${r?.change_order_number ?? ''} — ${r?.title ?? ''}</p>${ok ? `<p>Revised contract: $${Number(r.revised_contract_value ?? 0).toLocaleString('en-US')}</p>` : ''}</body></html>`;
return [{ json: { html } }];
